function wallArt() {
  const candidates = [
    ["west", 2.3],
    ["west", -2.7],
    ["north", -4.6],
    ["north", 4.1],
    ["east", -2.8],
    ["south", -4.4],
    ["south", 2.6]
  ];
  for (const [wall, offset] of candidates) {
    const blocked = allOpenings.some(o => {
      if (o.wall !== wall) return false;
      const w = Number.isFinite(o.width) ? o.width : 1.2;
      const center = Number.isFinite(o.offset) ? o.offset : 0;
      const bottom = Number.isFinite(o.bottom) ? o.bottom : 0;
      const height = Number.isFinite(o.height) ? o.height : 2.4;
      return Math.abs(offset - center) < (w + 1.15) / 2 + 0.15 &&
        bottom < 2.55 && bottom + height > 1.7;
    });
    if (blocked) continue;
    const frame = api.wallFrame(wall, offset, 1.7, 0.035);
    api.place({
      assetId: api.asset("art"),
      name: "公寓抽象艺术画",
      position: frame.point,
      facing: { direction: frame.inward },
      dimensions: specs.art.dimensions,
      role: "decor"
    });
    return;
  }
  api.place({
    assetId: api.asset("art"),
    name: "卧室隔墙艺术画",
    position: api.roomPoint(-5.0, -0.59, 1.7),
    rotationY: Math.PI,
    dimensions: specs.art.dimensions,
    role: "decor"
  });
}
